#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=11

# Stichtag: Live geht auf SharePoint, der Bestand zieht um, Dropbox wird abgeschaltet.
# Strangler: erst DB, dann Functions, dann Client; alle Weichen stehen bis zum Stichtag auf
# dropbox, der laufende Betrieb auf v2 merkt bis dahin nichts.
# Voraussetzung: Schritte 1–3 erledigt, Staging abgenommen (Prototyp + Upload/Abgleich/Rechte).
# Aufruf: bash scripts/medienablage/4-stichtag.sh

ENV_FILE=".env"
STAGING_ENV=".env.staging"
SECRETS_DIR=".secrets"
NETLIFY_IMPORT="$SECRETS_DIR/netlify-live-ablage.env"
MIGRATIONEN=(
  supabase/migrations/20261129_asset_poster.sql
  supabase/migrations/20261130_custom_column_assets_rls.sql
  supabase/migrations/20261201_medienablage.sql
  supabase/migrations/20261202_medienablage_creator_umzug.sql
)
mkdir -p "$SECRETS_DIR"; chmod 700 "$SECRETS_DIR"

staging_value() { ENV_FILE="$STAGING_ENV" _existing "$1" || true; }
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# sql DB "query" gibt das Ergebnis ohne Kopf aus (eine Zeile pro Datensatz, | getrennt).
sql() { psql "$1" -v ON_ERROR_STOP=1 -At -F ' | ' -c "$2"; }

banner "Medienablage · Schritt 4: Stichtag und Umzug"

stage "Werkzeuge und Zugänge"
for bin in psql node curl; do
  if command -v "$bin" >/dev/null 2>&1; then ok "$bin"; else warn "$bin fehlt"; fi
done
for k in MS_TENANT_ID MS_CLIENT_ID SP_SITE_URL SP_SITE_ID SP_DRIVE_ID; do
  if [[ -n "$(_existing "$k" || true)" ]]; then ok "$k in $ENV_FILE"; else warn "$k fehlt in $ENV_FILE (Schritt 2)"; fi
done
[[ -n "$(staging_value STAGING_DB_URL)" ]] && ok "STAGING_DB_URL in $STAGING_ENV" || warn "STAGING_DB_URL fehlt (Schritt 3)"
step "Live-Dashboard → Connect → Session pooler → URI kopieren"
note "Nur für diesen Lauf, außer du hast sie über die Eingabeseite in .env gespeichert (dann Enter)."
ask_secret LIVE_DB_URL "Live-DB-URL (postgresql://…):"
ask APP_URL "Live-URL des CRM (https://…):"
write_env APP_URL "$APP_URL"
pause

stage "Migrationen: Staging, dann Live"
say "Alle vier sind nur additiv: neue Spalten mit Default 'dropbox', neue Tabellen, neue Funktionen."
say "Der Client auf v2 läuft danach unverändert weiter."
STAGING_DB_URL="$(staging_value STAGING_DB_URL)"
for ziel in staging live; do
  db="$STAGING_DB_URL"; [[ "$ziel" == live ]] && db="$LIVE_DB_URL"
  [[ -n "$db" ]] || { warn "$ziel: keine DB-URL"; continue; }
  stand=$(sql "$db" "select coalesce(to_regclass('public.ablage_stand')::text,'–') || ' / ' || coalesce(to_regclass('public.ablage_umzug')::text,'–')" 2>/dev/null || echo "?")
  say "${BOLD}${ziel}${RESET}: ablage_stand / ablage_umzug = $stand"
  for f in "${MIGRATIONEN[@]}"; do
    if confirm "$f auf $ziel anwenden?"; then
      psql "$db" -v ON_ERROR_STOP=1 -q -f "$f" && ok "$ziel: $f"
    fi
  done
done
note "Reihenfolge einhalten; jede Datei ist in sich eine Transaktion und idempotent (IF NOT EXISTS)."
pause

stage "Functions und Env auf Live"
# Einmal erzeugt, dann aus .env: ein neuer SP_WEBHOOK_CLIENT_STATE wuerde das laufende Abo verwerfen.
for k in SP_WEBHOOK_CLIENT_STATE ABLAGE_SECRET; do
  [[ -n "$(_existing "$k" || true)" ]] || write_env "$k" "$(openssl rand -hex 32)"
done
umask 077
{
  for k in MS_TENANT_ID MS_CLIENT_ID SP_SITE_URL SP_SITE_ID SP_DRIVE_ID SP_WEBHOOK_CLIENT_STATE ABLAGE_SECRET; do
    printf '%s=%s\n' "$k" "$(_existing "$k" || true)"
  done
  printf 'ABLAGE_UMZUG_PARALLEL=2\n'
} > "$NETLIFY_IMPORT"
if confirm "Zertifikat aus .secrets in den Live-Vault schreiben?"; then
  node scripts/medienablage/vault-setzen.mjs --env "$ENV_FILE" \
    --key "$SECRETS_DIR/medienablage-app.key" --cert "$SECRETS_DIR/medienablage-app.crt" \
    || warn "Fehlgeschlagen: Ausgabe oben prüfen."
fi
open_url "https://app.netlify.com/"
step "Live-Site → Site configuration → Environment variables → Import from a .env file"
step "Inhalt von $(pwd)/$NETLIFY_IMPORT einfügen (vorhandene Werte NICHT überschreiben, falls schon gesetzt)"
note "CREATOR_UPLOAD_TOKEN_KEY auf Live nicht anfassen: ein neuer Schlüssel macht offene Creator-Links ungültig."
step "Schalter umlegen: src/core/ablage/schalter.json auf \"dropboxUpload\": false (oder Netlify-Env VITE_DROPBOX_UPLOAD=off, Scope All), mit dem Merge ausrollen"
note "Erst nach den Migrationen oben: sonst fragen Client und Server ablage-Spalten ab, die es auf Live nicht gibt."
note "Danach nicht mehr zurück auf on: SharePoint-Dateien wären unsichtbar. Rückweg ist der Notschalter."
step "Merge feat/medienablage → staging (abgenommen) → v2, außerhalb der Arbeitszeit. Deploy abwarten."
note "Functions und Client kommen im selben Deploy. Unkritisch, weil alle Weichen auf dropbox stehen."
pause "Deploy live? Enter"

stage "Smoke-Test Live (alles noch Dropbox)"
open_url "${APP_URL%/}/admin/medienablage"
step "Karten: 'Abgleich' letzter Erfolg < 2 Minuten, 'Webhook-Abo' mit Ablaufdatum, 'Zertifikat' mit Datum"
step "Weichen-Tabelle: alle Unternehmen auf dropbox"
step "In einem echten Unternehmen ein Video hochladen und abspielen: muss wie bisher über Dropbox laufen"
step "Creator-Link eines echten Auftrags öffnen: Upload startet wie bisher"
sql "$LIVE_DB_URL" "select drive_id, letzter_erfolg, abo_ablauf, fehler from ablage_stand" 2>/dev/null || warn "ablage_stand nicht lesbar"
pause

stage "Abnahme mit dem Test-Unternehmen auf Live"
say "Weiche des Testunternehmens auf sharepoint (Admin-Seite). Es landet unter _Test."
step "Video im CRM hochladen → liegt in SharePoint unter _Test/…/Feedbackschleife_1/A, spielt im CRM ab"
step "Datei im Finder (OneDrive-Sync) in eine Variante legen → nach ~2 Minuten im CRM"
step "Variante umbenennen, Datei löschen (CRM): SharePoint folgt; Löschen im Finder als Mitarbeiter: gesperrt"
step "Creator-Link des Test-Auftrags: Upload landet in der nächsten Feedbackschleife"
step "Kunden-Leselink erzeugen und im privaten Fenster öffnen"
step "Notschalter an → Upload geht nach Dropbox → Notschalter aus"
note "Rechte: ein Mitarbeiter sieht _Test NICHT (nur Admins); echte Unternehmen erst nach dem Stichtag prüfbar."
pause "Abnahme bestanden? Enter"

stage "OneDrive-Quellen für den Umzug freigeben"
say "Die alten Video-Links zeigen in die persönlichen OneDrives einzelner Mitarbeiter."
say "Die App (Sites.Selected) braucht darauf Lesezugriff, sonst endet die Zeile mit 'onedrive_kein_zugriff'."
node scripts/medienablage/onedrive-freigeben.mjs --env "$ENV_FILE" || warn "Auflisten fehlgeschlagen"
open_url "https://developer.microsoft.com/de-de/graph/graph-explorer"
step "Als Admin anmelden, 'Berechtigungen ändern' → Sites.FullControl.All, Reiter 'Zugriffstoken' kopieren"
ask_secret GRAPH_ADMIN_TOKEN "Admin-Token (wird nicht gespeichert):"
if [[ -n "$GRAPH_ADMIN_TOKEN" ]]; then
  node scripts/medienablage/onedrive-freigeben.mjs --env "$ENV_FILE" --token "$GRAPH_ADMIN_TOKEN" || warn "Nicht alle Sites freigegeben, Ausgabe oben prüfen."
fi
note "Ordner-Links (:f:) übernimmt der Umzug nicht (Grund 'onedrive_ordner'): Inhalte von Hand in den Fachordner legen."
pause

stage "Stichtag (außerhalb der Arbeitszeit)"
say "Ab jetzt landen alle neuen Uploads in SharePoint. Team vorher informieren, laufende Uploads abwarten."
sql "$LIVE_DB_URL" "select ablage_ziel, count(*) from unternehmen group by 1" || true
if confirm "Alle Unternehmen auf sharepoint stellen?"; then
  sql "$LIVE_DB_URL" "update unternehmen set ablage_ziel = 'sharepoint' where ablage_ziel is distinct from 'sharepoint' returning firmenname" | tail -n 5
  ok "Weichen umgestellt"
fi
warn "Rückweg ohne Deploy: Admin-Seite → Notschalter 'Alle Uploads zurück zu Dropbox'."
note "Danach prüfen: Rechte-Karte auf der Admin-Seite (läuft binnen einer Minute an), ein Mitarbeiter sieht seine Unternehmen im OneDrive."
pause

stage "Umzug des Bestands starten"
say "Pro Unternehmen über die Admin-Seite ('Bestand umziehen') oder alle auf einmal hier."
say "Der Zeitplan stößt jede Minute bis zu ABLAGE_UMZUG_PARALLEL Läufer an (Standard 2)."
if confirm "Bestand aller SharePoint-Unternehmen einreihen?"; then
  sql "$LIVE_DB_URL" "select u.firmenname, public.ablage_umzug_anlegen(s.drive_id, u.id) from unternehmen u cross join ablage_stand s where u.ablage_ziel = 'sharepoint' order by 2 desc" | head -n 30
fi
note "Unternehmen, die erst später umgestellt werden, holt ein erneuter Aufruf nach (bereits eingereihte bleiben unberührt)."
note "Dropbox-Dateien ohne CRM-Zeile werden NICHT umgezogen (lose Dateien, alte Ordner)."
pause

stage "Umzug überwachen"
open_url "${APP_URL%/}/admin/medienablage"
sql "$LIVE_DB_URL" "select status, count(*), pg_size_pretty(sum(coalesce(groesse,0))) from ablage_umzug group by 1 order by 1" || true
say ""
say "Fehler und Übersprungene nach Grund:"
sql "$LIVE_DB_URL" "select status, grund, count(*) from ablage_umzug where status in ('fehler','uebersprungen') group by 1,2 order by 3 desc" || true
say ""
note "dropbox_fehlt        Datei nicht (mehr) unter file_path → in Dropbox suchen, Zeile von Hand korrigieren"
note "onedrive_kein_zugriff Site nicht freigegeben → Stufe 'OneDrive-Quellen' wiederholen, dann erneut einreihen"
note "onedrive_weg         Link gelöscht/abgelaufen → beim Ersteller nachfragen"
note "onedrive_ordner      Ordner-Link → von Hand"
note "item_doppelt         zwei CRM-Zeilen auf derselben Datei → Doublette im CRM bereinigen"
note "ohne_kooperation     Asset ohne Kooperation → Datenleiche"
note "sonstige             voruebergehend (Graph/Dropbox), sechs Versuche mit Backoff bis 1 h"
say ""
note "Erneut einreihen (öffnet nur Zeilen mit Status fehler):"
note "  select ablage_umzug_anlegen(drive_id, '<unternehmen_id>') from ablage_stand;"
note "Drosselt Graph (429 im Log) → ABLAGE_UMZUG_PARALLEL auf 1; läuft sauber → bis 4 erhöhen."
pause "Umzug durch (offen = 0)? Enter"

stage "Abschluss: prüfen, Kunden informieren, Dropbox abschalten"
say "Restbestand pro Unternehmen (Originale noch in Dropbox):"
sql "$LIVE_DB_URL" "select u.firmenname, count(*) filter (where a.ablage = 'dropbox') as dropbox, count(*) filter (where a.ablage = 'sharepoint') as sharepoint
  from (select kooperation_id, ablage from kooperation_bilder_asset where source_asset_id is null
        union all select kv.kooperation_id, x.ablage from kooperation_video_asset x join kooperation_videos kv on kv.id = x.video_id where x.source_asset_id is null
        union all select kv.kooperation_id, x.ablage from kooperation_story_asset x join kooperation_videos kv on kv.id = x.video_id where x.source_asset_id is null) a
  join kooperationen k on k.id = a.kooperation_id join kampagne ka on ka.id = k.kampagne_id join unternehmen u on u.id = ka.unternehmen_id
  group by 1 having count(*) filter (where a.ablage = 'dropbox') > 0 order by 2 desc" || true
note "Sollte nur noch die Fehler/Übersprungenen aus der letzten Stufe enthalten."
say ""
say "Mail an Kunden (Vorlage):"
note "  Betreff: Neuer Ort für Ihre Videos"
note "  Ab sofort liegen alle Videos Ihrer Kampagnen im CRM unter 'Videos'. Den bisherigen Dropbox-Links"
note "  folgt ab <Datum> nichts mehr. Einen Ordner-Link (1 Jahr gültig) erzeugen Sie selbst über"
note "  'Ordner-Link' im Videos-Tab, oder wir schicken ihn Ihnen."
say ""
if [[ -n "${GRAPH_ADMIN_TOKEN:-}" ]] && confirm "Lesezugriff der App auf die persönlichen OneDrives wieder entziehen?"; then
  node scripts/medienablage/onedrive-freigeben.mjs --env "$ENV_FILE" --token "$GRAPH_ADMIN_TOKEN" --entziehen || true
fi
step "Dropbox 30 Tage nur lesend lassen (die Weichen schreiben nicht mehr hinein), dann Ordner archivieren"
step "Danach DROPBOX_* aus den Netlify-Env-Variablen entfernen und den Dropbox-Plan kündigen"
note "Der Dropbox-Code bleibt bis dahin im Repo; sein Ausbau ist ein eigener Schritt."
unset LIVE_DB_URL GRAPH_ADMIN_TOKEN
pause

finish
note "Notschalter: Admin-Seite → 'Alle Uploads zurück zu Dropbox' (wirkt sofort, ohne Deploy)."
